<div class="mt-5 grid gap-6 xl:grid-cols-[minmax(0,1fr)_330px]"><div class="space-y-5"><section id="asistentes" class="ios-card p-5 sm:p-6"><div class="section-heading"><span class="section-icon"><?= icon('users','h-5 w-5') ?></span><div><h2>Participación y asistencia</h2><p>Confirma únicamente asistencia real. La evaluación conserva la escala utilizada por el instructor.</p></div></div><div class="mt-5 space-y-3"><?php if(!$attendees): ?><p class="rounded-xl bg-slate-50 p-4 text-xs text-slate-400">Sin participantes registrados.</p><?php endif; ?><?php foreach($attendees as$attendee): ?><article class="rounded-xl border border-slate-100 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><div><p class="text-sm font-semibold"><?= e($attendee['nombre']) ?></p><p class="mt-1 text-[10px] text-slate-400"><?= e($attendee['documento']) ?> · <?= e($attendee['vinculacion']) ?></p></div><span class="badge <?= $attendee['asistio']?'badge-green':'badge-gray' ?>"><?= $attendee['asistio']?'Asistió':'Pendiente' ?></span></div><?php if($training['estado']!=='Realizada'): ?><form method="post" action="<?= e(url('/capacitaciones/'.$training['id'].'/asistentes/'.$attendee['id'])) ?>" class="mt-3 grid items-end gap-3 sm:grid-cols-[150px_130px_1fr_auto]"><?= csrf_field() ?><label class="flex items-center gap-2 text-xs"><input type="checkbox" name="asistio" value="1"<?= $attendee['asistio']?' checked':'' ?>> Asistencia confirmada</label><div><label class="label">Evaluación</label><input type="number" min="0" step="any" name="evaluacion" class="input" value="<?= e($attendee['evaluacion']) ?>"></div><div><label class="label">Eficacia individual / observación</label><input name="eficacia" class="input" value="<?= e($attendee['eficacia']) ?>"></div><button class="btn-secondary" type="submit">Guardar</button></form><form method="post" action="<?= e(url('/capacitaciones/'.$training['id'].'/asistentes/'.$attendee['id'].'/eliminar')) ?>" class="mt-2" data-confirm="¿Retirar este participante?"><?= csrf_field() ?><button class="text-[10px] font-medium text-rose-600" type="submit">Retirar participante</button></form><?php else: ?><p class="mt-2 text-xs text-slate-500">Evaluación: <?= e($attendee['evaluacion']??'No registrada') ?><?= $attendee['eficacia']?' · '.e($attendee['eficacia']):'' ?></p><?php endif; ?></article><?php endforeach; ?></div><?php if($training['estado']!=='Realizada'): ?><details class="mt-4 rounded-xl bg-slate-50 p-4"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Agregar participante</summary><form method="post" action="<?= e(url('/capacitaciones/'.$training['id'].'/asistentes')) ?>" class="mt-4 grid gap-3 sm:grid-cols-2"><?= csrf_field() ?><div class="sm:col-span-2"><label class="label">Persona del directorio (opcional)</label><select name="empleado_id" class="input"><option value="">Participante externo / digitación manual</option><?php foreach($employees as$employee): ?><option value="<?= (int)$employee['id'] ?>"><?= e($employee['nombre']) ?> · <?= e($employee['documento']) ?></option><?php endforeach; ?></select></div><div><label class="label">Nombre si es externo</label><input name="nombre" class="input" maxlength="180"></div><div><label class="label">Documento si es externo</label><input name="documento" class="input" maxlength="80"></div><div class="sm:col-span-2"><label class="label">Vinculación / cargo</label><input name="vinculacion" class="input" maxlength="180"></div><div class="sm:col-span-2 flex justify-end"><button class="btn-primary" type="submit">Agregar</button></div></form></details><?php endif; ?></section>
<section id="eficacia" class="ios-card p-5 sm:p-6"><h2 class="text-sm font-semibold">Eficacia de la formación</h2><p class="mt-1 text-xs text-slate-400">Evalúa transferencia al puesto, comportamiento o control del riesgo; no solo la asistencia.</p><?php if($training['eficacia']): ?><p class="mt-3 whitespace-pre-line rounded-xl bg-emerald-50 p-4 text-xs leading-5 text-emerald-900"><?= e($training['eficacia']) ?><span class="mt-2 block text-[10px]">Verificada el <?= format_date($training['fecha_eficacia']) ?></span></p><?php endif; ?><?php if($training['estado']==='Realizada'): ?><form method="post" action="<?= e(url('/capacitaciones/'.$training['id'].'/eficacia')) ?>" class="mt-4 grid items-end gap-3 sm:grid-cols-[1fr_170px_auto]"><?= csrf_field() ?><div><label class="label">Resultado de eficacia *</label><textarea name="eficacia" class="input min-h-20" required><?= e($training['eficacia']) ?></textarea></div><div><label class="label">Fecha *</label><input type="date" name="fecha_eficacia" class="input" required value="<?= e($training['fecha_eficacia']) ?>"></div><button class="btn-primary" type="submit">Guardar eficacia</button></form><?php endif; ?></section></div>
